const FusionRecipe* FindFusionRecipe(FusionPlantId existing, FusionPlantId used)
{
    size_t first = 0;
    size_t last = GetFusionRecipeCount();
    while (first < last)
    {
        const size_t middle = first + (last - first) / 2;
        const FusionRecipe& recipe = kRecipes[middle];
        if (recipe.existing < existing || (recipe.existing == existing && recipe.used < used))
            first = middle + 1;
        else
            last = middle;
    }
    if (first < GetFusionRecipeCount() && kRecipes[first].existing == existing && kRecipes[first].used == used)
        return &kRecipes[first];
    return nullptr;
}

const FusionRecipe* GetFusionRecipes()
{
    return kRecipes;
}

size_t GetFusionRecipeCount()
{
    return sizeof(kRecipes) / sizeof(kRecipes[0]);
}
